insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 1, 'Which function does energyEfficiency.priceSaving call to cost a tonne of carbon saved?', '["carbonAbatement.carbonIntensity", "carbonAbatement.abatementCurve", "carbonAbatement.abatementCost", "energyEfficiency.excessAirSaving"]'::jsonb, 2, 'SECTION 1: the Energy & Utilities Efficiency Studio''s cost per tonne is carbonAbatement.abatementCost called from inside energyEfficiency.priceSaving. SECTION 1 lists carbonIntensity and abatementCurve as other carbonAbatement functions, and excessAirSaving as an energyEfficiency function.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 2, 'What does the constant carbonAbatement.SCOPE hold?', '["ONE 1 and TWO 2", "ONE 1, TWO 2 and THREE 3", "ONE 1 only, with purchased energy as a flag", "DIRECT and PURCHASED, with no numbers"]'::jsonb, 0, 'SECTION 1 prints carbonAbatement.SCOPE: ONE 1, TWO 2. The inventory labels its totals Scope 1 (direct) and Scope 2 (purchased energy), and a line on scope 3 is blocked because it is not Scope 1 or Scope 2.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 3, 'A Business travel line on scope 3 is added to the complete Igbogene inventory. What does buildInventory do with it?', '["Adds it to the total, which then moves above 42945.777 tCO2e, and stays reportable.", "Drops it with no line and no reason, and the inventory stays reportable.", "Refuses the whole inventory, which then returns no total and names no line at all.", "Blocks it with its reason; the total stays 42945.777 tCO2e and reportable reads false."]'::jsonb, 3, 'SECTION 9: the scope 3 line is blocked with the reason "scope 3 is not Scope 1 or Scope 2, which is all this inventory totals". The totals stay the Scope 1 and Scope 2 figures of SECTION 7, total tCO2e 42945.777, and the inventory stops being reportable.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 4, 'A flare call reaches combustionCo2FromCarbon with the destruction efficiency null. What does the engine say?', '["REFUSED: The destruction efficiency must lie in (0, 1].", "REFUSED: A destruction efficiency is required. It is not read as 100 percent: for a flare it is the answer, and it is contested.", "REFUSED: A fuel quantity and the carbon per kilomole of fuel are required.", "REFUSED: A fuel quantity and a carbon content cannot be negative."]'::jsonb, 1, 'SECTION 2 prints the same refusal for a blank and for a null destruction efficiency. The interval refusal is for 0 or for 98 typed as a percentage, and the other two are the fuel refusals, one for a missing input and one for a negative fuel.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 5, 'combustionCo2FromCarbon({ fuelKmolPerYear: 1000, carbonPerKmolFuel: 1 }) leaves the destruction efficiency out of the call. What does it answer?', '["destructionEfficiencyFraction 0.98, co2Tonnes 43.129, ch4Tonnes 0.321", "destructionEfficiencyFraction 0.99, co2Tonnes 43.569, ch4Tonnes 0.160", "destructionEfficiencyFraction 1, co2Tonnes 44.009, ch4Tonnes 0.000", "A refusal naming the destruction efficiency as required"]'::jsonb, 2, 'SECTION 2: left out of the call, the destruction efficiency takes its stated default of complete combustion, and this call answers destructionEfficiencyFraction 1, co2Tonnes 44.009, ch4Tonnes 0.000. The refusal is for a blank or null box. The 0.98 and 0.99 rows are SECTION 3 calls with the efficiency typed.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 6, 'The digest says who the default of complete combustion is for. What does it say?', '["A burner is the case it is for; a flare is asked for its efficiency every time.", "A flare is the case it is for; a burner is asked for its efficiency every time.", "Every source, burner or flare, whenever the destruction efficiency box is blank.", "No source at all: the argument has no default and must always be typed."]'::jsonb, 0, 'SECTION 2 prints: "A burner is the case that default is for. A flare is asked for its efficiency every time." A blank box is refused, and an argument left out takes the stated default, so the argument does have one.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 7, 'carbonIntensity is called with no boundary named. What does the engine say?', '["REFUSED: A positive denominator is required.", "REFUSED: A registered emission factor is required.", "REFUSED: A global warming potential must be positive. Refused for CH4, so the set is not declared.", "REFUSED: A boundary must be named. Tonnes per tonne charged and tonnes per tonne of saleable product are different numbers for the same plant, and an intensity without its boundary cannot be compared with anything."]'::jsonb, 3, 'SECTION 2 prints the boundary refusal for this call. carbonIntensity gives the denominator refusal for a denominator of 0 or a blank one; the factor refusal belongs to emissionLine and the GWP refusal to makeGwpSet.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 8, 'A named boundary and a denominator of 0 reach carbonIntensity. What comes back?', '["An intensity with reportable set to false", "REFUSED: A positive denominator is required.", "REFUSED: A boundary must be named.", "The total tCO2e, with the denominator read as 1"]'::jsonb, 1, 'SECTION 2 prints "REFUSED: A positive denominator is required." for a denominator of 0 and for a blank denominator. The boundary refusal is for a call with no boundary named, and no row reads a 0 or a blank as some other figure.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 9, 'makeGwpSet is given a methane GWP of 0. What comes back?', '["A set declared true that converts methane at 0", "A refusal for CH4, with the set still declared true", "A refusal for CH4, and the set reads declared false", "A set declared true, with CH4 read as the CO2 value of 1"]'::jsonb, 2, 'SECTION 2: a methane GWP of 0, and one of -5, return "REFUSED: A global warming potential must be positive. Refused for CH4, so the set is not declared." The set then reads declared false.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 10, 'What does makeGwpSet({}) return?', '["label none, gases 0, declared false", "label none, gases 4, declared true", "REFUSED, with no set returned at all", "the course''s set, declared true"]'::jsonb, 0, 'SECTION 1 prints the row for makeGwpSet({}): label none, gases 0, declared false. Neither module exports a global warming potential, and SECTION 6 declares a set only with a label and at least one value.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 11, 'A factor is typed with a value of 2.5 tCO2/t and nothing else. What does its record read?', '["hasValue false, provenanceComplete false, and missingProvenance value, source", "hasValue true, provenanceComplete false, missingProvenance source, version", "hasValue true, provenanceComplete true, and missingProvenance none at all", "A refusal from emissionLine, with no record returned at all"]'::jsonb, 1, 'SECTION 1 prints the row for "A factor typed with no source": value 2.5, unit tCO2/t, gas CO2, hasValue true, provenanceComplete false, missingProvenance source, version. A value with nothing else is still a record, and the record says what it lacks.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 12, 'Which of these does neither engine module export?', '["A molar mass each for carbon, CO2 and methane, in kg/kmol", "A table of fuels with typical LHV and HHV heating values", "A list of heating value bases, reading LHV and HHV", "An emission factor or a global warming potential"]'::jsonb, 3, 'SECTION 1: "Neither module exports an emission factor or a global warming potential." carbonAbatement exports MW_C, MW_CO2 and MW_CH4, and energyEfficiency exports FUEL_REFERENCE with typical heating values and HEATING_VALUE_BASIS: LHV, HHV.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 13, 'What does FUEL_REFERENCE_NOTE say about the heating values in energyEfficiency''s fuel table?', '["They are definitional, like the atom counts, and drive the stoichiometry.", "They are the IUPAC values, and no fuel analysis may change them in a call.", "They are typical: the fuel analysis governs, and a measured value should replace these.", "They are defaults the engine reads whenever a heating value box is blank."]'::jsonb, 2, 'SECTION 1''s note on the fuel table labels the heating values typical, says the fuel analysis governs, and asks for a measured value in their place. The definitional label belongs to the atom counts.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 14, 'Which Igbogene line is the one line on Scope 2?', '["Vented and fugitive methane, 4231.600 tCO2e", "Purchased electricity, 12915.000 tCO2e", "Flaring (CO2), 2191.807 tCO2e", "Fired heaters (CO2), 23121.448 tCO2e"]'::jsonb, 1, 'SECTION 7 prints Purchased electricity on scope 2 at 12915.000 tCO2e, and Scope 2 is the sum of its 1 line. The heaters, the flare''s two lines and the vented methane are the 4 lines of Scope 1.'),
  ('carbon', 'beginner', 'module', 'm01-what-an-inventory-counts', 15, 'PROPERTY_REFERENCE lists a latent heat of vaporisation of water of 2442 kJ/kg. How does the table label it?', '["Measured on the Igbogene fuel gas", "Definitional, like the atom counts", "A default the stack loss applies unlabelled", "Typical, at a 25 C reference"]'::jsonb, 3, 'SECTION 1 heads the table "typical values a stack loss needs, each labelled as typical", and the waterLatentHeatKJkg row reads 2442, at 25 C reference.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 1, 'What does the engine''s own statement of its combustion method say the atom balance needs as a source?', '["A registered emission factor with its source and its version", "No source document, because it is conservation of mass", "The declared GWP set, which converts the carbon it counts", "The fuel supplier''s statement for the year it is run on"]'::jsonb, 1, 'SECTION 3 quotes the method verbatim: "Atom balance: carbon in equals CO2 out. This is conservation of mass, so it needs no source document." In SECTION 7 each atom-balance line carries the source "Atom balance (conservation of mass)" and the version "not applicable"; the registered factors carry a source and a version.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 2, 'One thousand kilomoles of a fuel with one carbon atom a molecule are burned at a destruction efficiency of 0.98. What does the engine return?', '["co2Tonnes 43.569 and ch4Tonnes 0.160", "co2Tonnes 41.809 and ch4Tonnes 0.802", "co2Tonnes 44.009 and ch4Tonnes 0.000", "co2Tonnes 43.129 and ch4Tonnes 0.321"]'::jsonb, 3, 'SECTION 3 prints the 0.98 row as carbon kmol 1000.000, co2Tonnes 43.129, ch4Tonnes 0.321. The other pairs are the rows for 0.99, 0.95 and complete combustion at 1.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 3, 'In the 1000 kmol table, what does the carbon kmol column do as the destruction efficiency falls from 1 to 0.95?', '["It reads 1000.000 in every row.", "It falls with the efficiency, as co2Tonnes does.", "It rises with the efficiency, as ch4Tonnes does.", "It is blank below 1, as escaped carbon is not counted."]'::jsonb, 0, 'SECTION 3 prints carbon kmol 1000.000 on all four rows. The destruction efficiency divides that carbon between CO2 and methane: co2Tonnes falls from 44.009 to 41.809 and ch4Tonnes rises from 0.000 to 0.802.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 4, 'Each kilomole of carbon that escapes combustion leaves as how many kilograms of methane?', '["MW_CO2, which is 44.009", "MW_C, which is 12.011 alone", "MW_CH4, which is 16.043", "The C2H6 molar mass, 30.070"]'::jsonb, 2, 'SECTION 3: "Each kilomole that escapes leaves as MW_CH4 kilograms of methane." SECTION 1 prints carbonAbatement.MW_CH4: 16.043. MW_CO2 weighs the carbon that burns, and 30.070 is ethane''s row in FUEL_REFERENCE.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 5, 'The Igbogene fired heaters burn 482000 kmol of fuel a year at 1.09 kmol of carbon per kmol, all invented. What carbonKmolPerYear does the engine return?', '["482000 kmol", "525380.000 kmol", "50820.000 kmol", "23121.448 kmol"]'::jsonb, 1, 'SECTION 4 prints carbonKmolPerYear 525380.000 for the heaters. 482000 is the fuel quantity typed in, 50820.000 is the flare''s carbon in SECTION 5, and 23121.448 is the heaters'' co2Tonnes, a mass of CO2 in tonnes.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 6, 'The same Igbogene heaters are run with a lower destruction efficiency typed, 0.995. What does the engine return?', '["co2Tonnes 23098.327 and ch4Tonnes 8.429", "co2Tonnes 23121.448 and ch4Tonnes 0.000", "co2Tonnes 22272.955 and ch4Tonnes 8.429", "co2Tonnes 23005.841 and ch4Tonnes 42.143"]'::jsonb, 3, 'SECTION 4 prints the 0.995 row as 23005.841 t of CO2 and 42.143 t of methane. The 0.999 row is 23098.327 and 8.429, and at the typed 1 the heaters return 23121.448 and 0.000. 22272.955 is the heaters'' co2Tonnes in the row for a carbon per kmol of 1.05.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 7, 'The heaters'' fuel stays at 482000 kmol a year and the carbon per kilomole of fuel is typed as 1.05. What is co2Tonnes?', '["21212.338", "23121.448", "22272.955", "24394.189"]'::jsonb, 2, 'SECTION 4 prints the carbon per kmol table: 1.00 gives 21212.338, 1.05 gives 22272.955, the Igbogene 1.09 gives 23121.448 and 1.15 gives 24394.189 t of CO2.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 8, 'How does the digest describe the Igbogene heaters'' carbon per kilomole of fuel, 1.09?', '["The fuel analysis read as carbon atoms, typed in as an input", "A default the engine applies when that box is left out", "A value read from the FUEL_REFERENCE methane row", "The supplier statement (invented), version 2025"]'::jsonb, 0, 'SECTION 4: "The carbon per kilomole of fuel is the fuel analysis read as carbon atoms: the Igbogene figure is an input." SECTION 2 refuses a call with the carbon per kmol left out, so there is no default, and the supplier statement is the source of the electricity factor in SECTION 7.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 9, 'Which two flare calls get the same refusal, "The destruction efficiency must lie in (0, 1]."?', '["A blank destruction efficiency and one of 0", "A destruction efficiency of 0 and one of 98", "A destruction efficiency of 98 and a fuel of -1 kmol", "A destruction efficiency of 1 and one of 98"]'::jsonb, 1, 'SECTION 2 prints the interval refusal for 0 and for 98 typed as a percentage. A blank is refused as required, a fuel of -1 kmol is refused as negative, and 1 lies inside (0, 1], so it computes: SECTION 3 prints a row at 1.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 10, 'A flare call leaves the carbon per kilomole of fuel out. What does the engine say?', '["REFUSED: A fuel quantity and a carbon content cannot be negative.", "REFUSED: The destruction efficiency must lie in (0, 1].", "It computes at a stated default of 1 kmol of carbon a kmol of fuel.", "REFUSED: A fuel quantity and the carbon per kilomole of fuel are required."]'::jsonb, 3, 'SECTION 2 prints "REFUSED: A fuel quantity and the carbon per kilomole of fuel are required." for the carbon per kmol left out and for a blank fuel. The destruction efficiency left out of the call takes its stated default of complete combustion; the carbon per kmol left out is refused.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 11, 'Fuel typed as -1 kmol on the flare: which refusal follows?', '["REFUSED: A fuel quantity and a carbon content cannot be negative.", "REFUSED: A fuel quantity and the carbon per kilomole of fuel are required.", "REFUSED: The destruction efficiency must lie in (0, 1].", "REFUSED: A registered emission factor is required."]'::jsonb, 0, 'SECTION 2 prints the negative refusal for a fuel of -1 kmol. The "are required" refusal is for a blank fuel or a carbon per kmol left out, the interval refusal is for the efficiency, and the factor refusal belongs to emissionLine.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 12, 'Which keys does combustionCo2FromCarbon''s result carry for the gases it computes?', '["co2Tonnes, ch4Tonnes and n2oTonnes", "co2Tonnes only, with methane left to a factor line", "co2Tonnes and ch4Tonnes, and no other gas", "one key in tCO2e, converted on the declared set"]'::jsonb, 2, 'SECTION 3: "The engine''s result carries these keys and no other gas: co2Tonnes, ch4Tonnes." Nitrous oxide from combustion is not computed by the atom balance (H4) and needs an emission factor line. In SECTION 7 the flare''s 16.306 t CH4 is converted at a GWP of 29.8 on IPCC AR6 GWP100, fossil methane.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 13, 'carbonAbatement.MW_CO2 reads 44.009. How does the digest say it is built?', '["12.011 plus four hydrogens at 1.008", "12.011 plus two oxygens at 15.999", "12.011 plus two oxygens at 16.043", "The carbon atom alone, at 12.011"]'::jsonb, 1, 'SECTION 3: MW_CO2 44.009 is 12.011 plus two oxygens at 15.999, and MW_CH4 16.043 is 12.011 plus four hydrogens at 1.008. MW_C, 12.011, is the carbon atom alone.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 14, 'The Igbogene heaters'' destruction efficiency is 1. How does SECTION 4 record it?', '["Left out of the call, so the stated default applied", "Taken from the operator''s flare study", "Typed in the call, for complete combustion", "Set by the engine for every burner call"]'::jsonb, 2, 'SECTION 4 lists the inputs as "destruction efficiency 1 (complete combustion, typed)". The stated default applies only to an argument left out of the call (SECTION 2), and the flare study states the flare''s 0.98.'),
  ('carbon', 'beginner', 'module', 'm02-carbon-in-co2-out', 15, 'The digest explains why 1000 kmol of carbon burned completely is 44.009 t of CO2. What is the explanation?', '["Each kilomole of carbon that burns leaves as MW_CO2 kilograms of CO2.", "A registered factor of 44.009 is applied to each tonne of the fuel burned.", "Each kilomole of carbon that burns leaves as MW_CH4 kilograms of CO2.", "The CO2 is weighed at MW_C and then converted at the set''s GWP."]'::jsonb, 0, 'SECTION 3 gives this as the reason 1000 kmol burned completely is 44.009 t. The method uses no registered factor, and MW_CH4 is for escaped carbon.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 1, 'Where does the Igbogene flare''s destruction efficiency of 0.98 come from?', '["It is the engine''s default for a flare, applied to a blank box.", "It is read from FUEL_REFERENCE beside the typical heating values.", "The operator''s flare study states it, and the figure is invented.", "It is the complete combustion default, 1, less the methane share."]'::jsonb, 2, 'SECTION 5: "The operator''s flare study states a destruction efficiency of 0.98 (invented)." SECTION 2 refuses a blank flare efficiency, and a flare is asked for its efficiency every time.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 2, 'What is the Igbogene flare''s carbonKmolPerYear at a destruction efficiency of 0.9?', '["50820.000, the same as at every other efficiency", "38500, the gas sent to the flare in a year", "525380.000, the same carbon as the heaters count", "Lower than at 1, since less of the carbon burns in the flame"]'::jsonb, 0, 'SECTION 5 prints carbonKmolPerYear 50820.000 at every efficiency: "The efficiency splits that carbon between CO2 and methane; it does not change it." 38500 kmol is the gas sent to the flare and 525380.000 is the heaters'' carbon in SECTION 4.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 3, 'On the course''s set, IPCC AR6 GWP100 fossil methane, what does the flare total at a destruction efficiency of 0.95?', '["2124.711 tCO2e", "1214.805 tCO2e", "4442.493 tCO2e", "3339.515 tCO2e"]'::jsonb, 3, 'The 0.95 row of SECTION 5 reads co2Tonnes 2124.711 and a methane line of 1214.805, in a column headed CO2 plus methane line that prints 3339.515. The 0.9 row prints 4442.493.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 4, 'The Igbogene flare is run at a destruction efficiency of 1. How does its methane appear in the table?', '["A methane line of 242.961 tCO2e beside 2236.537 t of CO2.", "No methane line at all; the flare is 2236.537 tCO2e.", "A methane line of 0.000 tCO2e, printed as a line of its own.", "It is refused, since a flare must lie below complete combustion."]'::jsonb, 1, 'SECTION 5 prints the row at 1 as co2Tonnes 2236.537, ch4Tonnes 0.000, methane line "no line (no methane)" and flare tCO2e 2236.537. The interval (0, 1] includes 1, so the call computes; 242.961 is the methane line at 0.99.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 5, 'Handed to atomBalanceLines, what does the flare refused for a blank destruction efficiency become?', '["0 lines, as for a source excluded on purpose", "Two lines computed at complete combustion", "1 line labelled Flaring that carries the refusal", "Two lines of 0.000 t each, counted unsourced"]'::jsonb, 2, 'SECTION 5: handed to atomBalanceLines, the refused flare becomes 1 line labelled Flaring that carries the refusal, so an inventory built with it is blocked on the flare. SECTION 9 prints 0 lines only for a source with excluded true, left out of the boundary on purpose.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 6, 'Read as 100 percent, the same flare is 2236.537 tCO2e with no methane line. How far below the flare at 0.98 is that?', '["485.922 tCO2e", "441.191 tCO2e", "242.961 tCO2e", "440.265 tCO2e"]'::jsonb, 1, 'SECTION 5 prints: "Read as 100 percent, the same flare is 2236.537 tCO2e with no methane line: 441.191 tCO2e below the flare at 0.98 (computed here from the engine''s figures)." 485.922 is the methane line at 0.98, 242.961 the methane line at 0.99, and 440.265 the flare''s methane line on IPCC AR6 GWP100, non-fossil methane (SECTION 8).'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 7, 'At 0.98, what share of the flare''s 2677.729 tCO2e does the digest print for the methane line?', '["0.011315", "0.051037", "0.098534", "0.181468"]'::jsonb, 3, 'SECTION 5: "At 0.98 the methane line is 485.922 tCO2e of the flare''s 2677.729 tCO2e, a share of 0.181468 (computed here from the engine''s figures)." The other three are SECTION 7 shares of the whole inventory''s total: the flare''s methane, the flare''s CO2 and the vented methane.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 8, 'Which methane potential does the engine''s note on escaped carbon tell a user to apply?', '["The non-fossil methane potential", "The fossil methane potential", "The CO2 value of 1, as for burned carbon", "The set''s N2O value"]'::jsonb, 1, 'SECTION 5 quotes the engine''s note on escaped carbon, and its middle sentence reads: "Use the fossil methane potential for it." The course converts every methane line on IPCC AR6 GWP100, fossil methane.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 9, 'What does the course hold, as H3, about carbon that escapes a flare?', '["Escaped carbon is counted at the gas''s own methane content, which each flare study measures and types in.", "Escaped carbon is counted as CO2 at a GWP of 1, the same way the carbon that burns is counted in the line.", "Every escaped atom is counted as methane; a method on the gas''s own methane content is the owner''s decision.", "Escaped carbon is left out of the inventory until the operator''s flare study has been filed and referenced."]'::jsonb, 2, 'SECTION 5 and SECTION 25: every carbon atom that escapes is counted as methane, the engine''s stated and conservative assumption. A method that uses the gas''s own methane content is a different method and is the owner''s decision; the course grades nothing that depends on changing it.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 10, 'Down the flare table from 1 to 0.9, what do co2Tonnes and the flare tCO2e do?', '["co2Tonnes falls to 2012.884 while the flare total rises to 4442.493 tCO2e", "Both fall, co2Tonnes to 2012.884 and the flare total to 2124.711 tCO2e", "co2Tonnes holds at 2236.537 while the methane line rises to 2429.610 tCO2e", "Both rise, co2Tonnes to 2457.133 and the flare total to 4442.493 tCO2e"]'::jsonb, 0, 'SECTION 5 prints co2Tonnes 2236.537 at 1 and 2012.884 at 0.9, and flare tCO2e 2236.537 at 1 and 4442.493 at 0.9. 2429.610 is the methane line at 0.9, 2124.711 the CO2 at 0.95 and 2457.133 the flare total at 0.99.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 11, 'The flare''s 0.99 row returns 8.153 t CH4. Which methane line in tCO2e sits beside it?', '["485.922 tCO2e", "2457.133 tCO2e", "8.153 tCO2e", "242.961 tCO2e"]'::jsonb, 3, 'SECTION 5 prints the 0.99 row: ch4Tonnes 8.153, methane line 242.961 tCO2e on IPCC AR6 GWP100, fossil methane (CH4 29.8), and flare tCO2e 2457.133. 485.922 is the methane line at 0.98. 8.153 is tonnes of methane, a different quantity from tCO2e.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 12, 'At 0.98 the flare''s inventory line "Flaring (unburned CH4)" shows 16.306 and 485.922. What are they?', '["16.306 tCO2e, and 485.922 t of methane on the course''s set", "16.306 t of methane, and 485.922 tCO2e on the course''s set", "16.306 t of CO2 burned, and 485.922 tCO2e for the whole flare", "16.306 t of methane, and 485.922 t of CO2 from the flare"]'::jsonb, 1, 'SECTION 7 prints the line with activity 16.306 t CH4, GWP 29.8, tonnes of gas 16.306 and tCO2e 485.922, on IPCC AR6 GWP100, fossil methane. The whole flare at 0.98 is 2677.729 tCO2e and its CO2 is 2191.807 t.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 13, 'Which destruction efficiency returns 81.531 t of methane from the Igbogene flare?', '["0.95, where the methane line is 1214.805 tCO2e", "0.9, where the methane line is 2429.610 tCO2e", "0.98, where the methane line is 485.922 tCO2e", "0.99, where the methane line is 242.961 tCO2e"]'::jsonb, 1, 'SECTION 5 prints ch4Tonnes 81.531 and a methane line of 2429.610 tCO2e on the 0.9 row. The 0.95, 0.98 and 0.99 rows return 40.765, 16.306 and 8.153 t of methane.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 14, 'Besides its destruction efficiency, which two inputs does the Igbogene flare call carry?', '["38500 kmol of gas a year, at 1.32 kmol of carbon per kmol", "482000 kmol of fuel a year, at 1.09 kmol of carbon per kmol", "38500 kmol of gas a year, at 1.09 kmol of carbon per kmol", "50820.000 kmol of gas a year, at 1.32 kmol of carbon per kmol"]'::jsonb, 0, 'SECTION 5 prints the flare''s inputs (invented): gas to the flare 38500 kmol a year, 1.32 kmol of carbon per kmol. 482000 kmol at 1.09 are the heaters'' inputs in SECTION 4, and 50820.000 is the flare''s carbonKmolPerYear.'),
  ('carbon', 'beginner', 'module', 'm03-the-flare-as-an-inventory-line', 15, 'At the stated 0.98, how many tonnes of CO2 does the flare''s CO2 line carry?', '["2236.537", "2677.729", "2191.807", "2214.172"]'::jsonb, 2, 'SECTION 5 prints co2Tonnes 2191.807 at 0.98, and SECTION 7 carries it as Flaring (CO2) at 2191.807 tCO2e. 2236.537 is the CO2 at 1, 2214.172 the CO2 at 0.99, and 2677.729 the flare''s CO2 plus its methane line at 0.98.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 1, 'Rebuilt on IPCC AR6 GWP100, non-fossil methane, what does the vented and fugitive methane line read?', '["4231.600 tCO2e", "4260.000 tCO2e", "3976.000 tCO2e", "3834.000 tCO2e"]'::jsonb, 3, 'SECTION 8 prints the vented line at 4231.600 on IPCC AR6 GWP100, fossil methane, 3834.000 on AR6 non-fossil, 4260.000 on AR5 fossil and 3976.000 on AR5 non-fossil. Only the methane lines move from set to set.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 2, 'The flare''s unburned methane line reads 489.183 tCO2e. On which set was it converted?', '["IPCC AR6 GWP100, fossil methane", "IPCC AR5 GWP100, fossil methane", "IPCC AR6 GWP100, non-fossil methane", "IPCC AR5 GWP100, non-fossil methane"]'::jsonb, 1, 'SECTION 8 prints Flaring (unburned CH4) at 485.922 on AR6 fossil, 440.265 on AR6 non-fossil, 489.183 on AR5 fossil and 456.571 on AR5 non-fossil.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 3, 'Which total does SECTION 8 print for the inventory on IPCC AR5 GWP100, non-fossil methane?', '["42660.826 tCO2e", "42945.777 tCO2e", "42502.520 tCO2e", "42977.438 tCO2e"]'::jsonb, 0, 'SECTION 8 prints the totals: 42945.777 on AR6 fossil, 42502.520 on AR6 non-fossil, 42977.438 on AR5 fossil and 42660.826 on AR5 non-fossil. Scope 2 is 12915.000 under all four.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 4, 'When the Igbogene inventory is rebuilt on another GWP set, which lines move?', '["Every line, since each set also rescales the CO2 lines it is given as well", "Only Scope 2, the purchased electricity line, on each of the sets", "Only the methane lines, since every CO2 line has a GWP of 1 on every set", "Only the flare''s two lines, since vented methane carries a factor of 1 in its line"]'::jsonb, 2, 'SECTION 8: "Only the methane lines move; every CO2 line has a GWP of 1 on every set." Scope 2 reads 12915.000 on all four sets, and the vented line moves with the set as the flare''s methane line does.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 5, 'Which two methane values does AR6 give in the sets the course prints?', '["30 for fossil methane and 28 for non-fossil", "29.8 for fossil methane and 27 for non-fossil", "27 for fossil methane and 29.8 for non-fossil", "29.8 for fossil methane and 273 for non-fossil"]'::jsonb, 1, 'SECTION 6 prints AR6 fossil CH4 29.8 and AR6 non-fossil CH4 27; AR5 gives 30 and 28. 273 is the AR6 value for N2O.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 6, 'What N2O value do both AR5 sets carry?', '["273", "28", "30", "265"]'::jsonb, 3, 'SECTION 6 prints N2O 265 on both AR5 sets and 273 on both AR6 sets. 28 and 30 are the AR5 methane values, non-fossil and fossil.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 7, 'Which makeGwpSet call returns a set the engine reads as declared?', '["A label with values, such as IPCC AR6 GWP100, fossil methane", "Values given with no label, however complete the values given are", "A label given with no values, such as a set name typed on its own", "A label with values that give methane a GWP of 0"]'::jsonb, 0, 'SECTION 6: a set is declared only with a label and at least one value. Values with no label, and a label with no values, both read declared false. SECTION 2 refuses a methane GWP of 0, and the set then reads declared false.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 8, 'The engine''s note on every GWP set says the set is stated on every result. What reason does the note give?', '["The operator must file on the report that the set names, in each year.", "The set also changes the CO2 lines, which then need a label.", "An inventory on one report is not comparable with one on another.", "The difference from the course set is computed on each result."]'::jsonb, 2, 'SECTION 6 quotes the note: "Global warming potentials differ between IPCC assessment reports. An inventory on one report is not comparable with one on another, so the set is stated on every result." Every CO2 line has a GWP of 1 on every set, and which report to file on is held (H1).'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 9, 'For which methane does the engine''s methane note call the fossil value the consistent one?', '["Unburned methane only; vented methane takes non-fossil", "Vented, fugitive and unburned fossil methane alike", "None: the note leaves either value open for every line", "Vented methane only; flare methane is counted as CO2"]'::jsonb, 1, 'SECTION 6 quotes the methane note on every set. It closes: "the fossil value is the consistent one for vented, fugitive and unburned fossil methane alike."'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 10, 'Measured from the course set, what does SECTION 8 print for the AR6 non-fossil total?', '["-284.951 tCO2e", "31.661 tCO2e", "0.000 tCO2e", "-443.257 tCO2e"]'::jsonb, 3, 'SECTION 8 prints the total less the course set as 0.000 on AR6 fossil, -443.257 on AR6 non-fossil, 31.661 on AR5 fossil and -284.951 on AR5 non-fossil (computed here).'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 11, 'What does the course state about which IPCC report a Nigerian operator should file on?', '["It is a regulatory reading and the owner''s decision; the course grades no choice between them.", "AR6, since every inventory in the course is computed on IPCC AR6 GWP100, fossil methane, as a rule.", "AR5, since the digest states that UNFCCC reporting has required it of operators until now.", "Whichever report gives the lower Igbogene total, which the digest prints for all four of the sets."]'::jsonb, 0, 'H1 holds the filing choice as a regulatory reading, with any recommended default left to the owner. Both reports are taught, and neither is graded as the answer.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 12, 'The four sets the course types in are tabulated in which document?', '["carbonAbatement''s own GWP table, shipped with the engine", "IPCC AR6 WG1 chapter 7 alone, for all four of the sets", "GHG Protocol, IPCC Global Warming Potential Values, version 2.0", "The supplier statement (invented), 2025, as for the factors"]'::jsonb, 2, 'SECTION 6: the four sets are IPCC 100-year values as tabulated in GHG Protocol, "IPCC Global Warming Potential Values", version 2.0, 7 August 2024, adapted from IPCC AR6 WG1 chapter 7 and IPCC AR5 WG1 chapter 8. The engine ships no GWP.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 13, 'Why does the course compute every inventory on IPCC AR6 GWP100, fossil methane?', '["AR6 is the report an operator must file on, as the course recommends.", "The engine counts escaped carbon as methane, as its methane note states.", "It is the set the engine applies when no set has been declared at all.", "It gives the lowest Igbogene total of the four sets the digest prints."]'::jsonb, 1, 'SECTION 6: "Every inventory in this course is computed on ''IPCC AR6 GWP100, fossil methane'', because the engine counts escaped carbon as methane" (the methane note). With no set declared, SECTION 9 blocks the vented line, and SECTION 8 prints a lower total, 42502.520, on AR6 non-fossil.'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 14, 'Where does the engine record which GWP set an inventory was converted on?', '["In each line''s factor record, as the source of that factor", "In the atom balance method sentence, beside conservation of mass", "In the comparability note alone, and nowhere on the inventory", "In gwpSetLabel on every result, and an intensity carries it too"]'::jsonb, 3, 'SECTION 8: "The engine states its set on every result (gwpSetLabel), and an intensity carries it too (SECTION 10)." SECTION 7 prints gwpSetLabel: IPCC AR6 GWP100, fossil methane on the complete inventory, and the factor records name sources such as the supplier statement (invented).'),
  ('carbon', 'beginner', 'module', 'm04-global-warming-potentials', 15, 'What horizon do all four of the course''s GWP sets share?', '["The horizon differs by report", "It differs between fossil and non-fossil", "100-year (GWP100)", "None is stated beside the values"]'::jsonb, 2, 'SECTION 6 prints the horizon column as 100-year (GWP100) on all four sets, AR6 and AR5, fossil and non-fossil.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 1, 'What source and version does the Igbogene purchased electricity factor carry in the complete inventory?', '["Supplier statement (invented), version 2025", "Epie Creek leak detection survey (invented), 2026 Q2", "Atom balance (conservation of mass), not applicable", "None, so the line is counted as unsourced"]'::jsonb, 0, 'SECTION 7 prints the Purchased electricity line with factor 0.41 tCO2/MWh (invented and SYNTHETIC), source "Supplier statement (invented)", version 2025 and provenance complete true. The survey is the vented methane''s source, the atom balance the combustion lines'', and the complete inventory has 0 unsourced lines.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 2, 'Why is the Igbogene first pass not reportable, as buildInventory states it?', '["1 factor(s) have no source or version; 2 line(s) could not be computed", "1 factor(s) have no source or version; 1 line(s) could not be computed", "the global warming potential set is not declared; 3 line(s) could not be computed", "1 factor(s) have no source or version"]'::jsonb, 2, 'SECTION 9 prints the first pass reason as "the global warming potential set is not declared; 3 line(s) could not be computed". The other three are the reasons at the next three steps: the GWP set declared, the flare efficiency entered, and the electricity factor entered with its source.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 3, 'Which step of the Igbogene inventory is the first that buildInventory reads as reportable?', '["The electricity factor entered with its source", "The flare efficiency entered", "The GWP set declared", "The survey referenced"]'::jsonb, 3, 'SECTION 9 prints reportable false on the first four steps and true only on "the survey referenced", whose reason reads none. The step before it totals the same 42945.777 tCO2e and is not reportable because 1 factor(s) have no source or version.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 4, 'In the first pass the vented methane survey is not referenced, yet the unsourced line count reads 0. What does the digest say?', '["An unsourced line is counted only once reportable is true.", "A blocked line is not also counted as unsourced.", "A factor of 1 needs no source, so the survey is not counted.", "The vented line was excluded on purpose, and adds no line."]'::jsonb, 1, 'SECTION 9: "The first pass has 3 blocked line(s) and 0 unsourced line(s); a blocked line is not also counted as unsourced." The vented line is blocked there for want of a GWP for CH4. At the next step the reason "1 factor(s) have no source or version" appears while reportable is still false.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 5, 'In the first pass, what does the engine name as blocking the Vented and fugitive methane line?', '["no global warming potential for CH4 in the declared set", "no factor value", "A registered emission factor is required.", "a negative activity: an emission line cannot remove tonnes"]'::jsonb, 0, 'SECTION 9 lists the first pass blocked lines: Flaring blocked by the destruction efficiency refusal, Vented and fugitive methane by "no global warming potential for CH4 in the declared set" and Purchased electricity by "no factor value". The other two reasons belong to the Diesel generators line and to the vented activity typed as -142 t.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 6, 'At the step "the GWP set declared", what does the Igbogene Scope 1 total read?', '["23121.448 tCO2e", "30030.777 tCO2e", "27353.048 tCO2e", "25799.177 tCO2e"]'::jsonb, 2, 'SECTION 9 prints Scope 1 at 23121.448 in the first pass, 27353.048 once the GWP set is declared and 30030.777 once the flare efficiency is entered. 25799.177 is the total of the inventory with a negative activity and a negative factor.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 7, 'The vented methane activity is typed as -142 t. What does buildInventory do with that line?', '["Subtracts 4231.600 tCO2e from the Scope 1 total.", "Reads it as 142.000 t and computes it as normal.", "Refuses the GWP set, so the set is not declared.", "Blocks it: an emission line cannot remove tonnes."]'::jsonb, 3, 'SECTION 9 prints the line "Vented methane typed as -142 t" with tCO2e none, blocked by "a negative activity: an emission line cannot remove tonnes". That inventory totals 25799.177 tCO2e and is not reportable.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 8, 'A Diesel generators line with no registered factor is added to the complete inventory. What reason does its blocked line carry?', '["no factor value, so it is read as zero", "A registered emission factor is required.", "scope 3 is not Scope 1 or Scope 2", "1 factor(s) have no source or version"]'::jsonb, 1, 'SECTION 9 prints the Diesel generators line with the reason "A registered emission factor is required." The scope 3 reason belongs to Business travel. With both lines added the total stays 42945.777 tCO2e and the inventory is not reportable because 2 line(s) could not be computed.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 9, 'The digest''s line shares of the Igbogene total, as printed, sum to 1.000001. What does its rounding note say?', '["Each share is rounded to six decimals; the unrounded shares sum to 1.", "A line is counted twice, once as CO2 and once as methane, in the total.", "The flare''s methane share is added to the flare''s CO2 share a second time.", "The total includes a blocked line that the shares leave out of the sum."]'::jsonb, 0, 'SECTION 7: "ROUNDING NOTE: the shares as printed sum to 1.000001; each is rounded to six decimals from the unrounded quotient, and the unrounded shares sum to 1." The complete inventory has 0 blocked lines.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 10, 'Over the boundary "Igbogene crude export only", what total intensity does carbonIntensity return?', '["0.01176597 tCO2e per barrel of oil exported", "0.01246090 tCO2e per barrel of oil exported", "0.00535892 tCO2e per barrel of oil exported", "0.01781982 tCO2e per barrel of oil exported"]'::jsonb, 3, 'SECTION 10 prints crude export only, denominator 2410000, Scope 1 intensity 0.01246090, Scope 2 intensity 0.00535892 and total intensity 0.01781982. 0.01176597 is the total over the inlet to export boundary, per barrel of oil equivalent produced.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 11, 'What two conditions does the engine''s comparability note on an intensity set?', '["The same denominator and the same reporting year for both", "The same boundary and the same Scope 2 electricity factor", "The same boundary and the same global warming potential set", "The same GWP set and a Scope 1 total of the same size"]'::jsonb, 2, 'SECTION 10 quotes the note: "Comparable only with an intensity on the same boundary (Igbogene flow station and gas plant, inlet to export) and the same global warming potential set (IPCC AR6 GWP100, fossil methane)."'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 12, 'With the electricity factor blank, what does the total intensity over the inlet to export boundary read?', '["0.01176597, reportable true", "0.00822761, reportable false", "0.00822761, reportable true", "REFUSED: A positive denominator is required."]'::jsonb, 1, 'SECTION 10: with the electricity factor blank the total intensity is 0.00822761 tCO2e per barrel of oil equivalent produced, reportable false, because 1 line(s) could not be computed. An intensity inherits its inventory''s status. 0.01176597 is the complete inventory''s total intensity.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 13, 'The engine''s disclaimer on the inventory names three things that belong in the compliance register. Which three?', '["Factors, sources and versions of each line", "Scope 1, Scope 2 and the total, in tCO2e", "Blocked lines, their reasons and the set", "Obligations, evidence and deadlines"]'::jsonb, 3, 'SECTION 7 quotes it: "This is a quantitative inventory. It is not a regulatory compliance register: obligations, evidence and deadlines belong in the compliance register, and keeping a second copy of them here would create two records that could disagree." The inventory itself carries each line''s factor, source and version, its totals and its blocked lines.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 14, 'In the first pass, Scope 2 reads 0.000 tCO2e. What does the digest show behind that figure?', '["Its one line, Purchased electricity, is blocked: no factor value.", "Igbogene bought no electricity in the year the first pass covers.", "The electricity line is on scope 3, which the inventory never totals.", "The factor 0.41 is present with no source, so it is counted as zero."]'::jsonb, 0, 'SECTION 9 lists Purchased electricity among the first pass blocked lines, "blocked: no factor value". Once the factor is entered with its source, Scope 2 reads 12915.000. SECTION 7 prints the line on scope 2 with an activity of 31500.000 MWh.'),
  ('carbon', 'beginner', 'module', 'm05-lines-factors-and-provenance', 15, 'Read as activity x factor x GWP, which row matches Purchased electricity?', '["31500.000 MWh at 0.41 tCO2/MWh and a GWP of 29.8: 4231.600 tCO2e", "12915.000 MWh at 0.41 tCO2/MWh and a GWP of 1: 31500.000 tCO2e", "31500.000 MWh at 0.41 tCO2/MWh and a GWP of 1: 12915.000 tCO2e", "31500.000 MWh at 1 tCO2/MWh and a GWP of 0.41: 12915.000 tCO2e"]'::jsonb, 2, 'SECTION 7 prints Purchased electricity: activity 31500.000 MWh, factor 0.41 tCO2/MWh (invented and SYNTHETIC), GWP 1, tonnes of gas 12915.000, tCO2e 12915.000. Every line is activity x factor x GWP (checked here). 4231.600 is the vented methane line, at a GWP of 29.8 on IPCC AR6 GWP100, fossil methane.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Under the rules in force, what becomes of a line that errors, or one off Scope 1 and Scope 2?', '["It is dropped from the inventory unseen", "It is a blocked line with its reason", "It is computed at 0.000 tCO2e instead", "It stops every total being computed"]'::jsonb, 1, 'SECTION 25 lists the rule "A line that errors, and a line off Scope 1 and Scope 2, is a blocked line with its reason" (SECTION 9). SECTION 9 names each blocked line with its reason, and the totals are still computed from the lines that did compute.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Held item H3 counts every escaped carbon atom as methane. Which Igbogene inventory line rests on that assumption?', '["Vented and fugitive methane, 142.000 t CH4", "Fired heaters (CO2), 23121.448 t CO2", "Flaring (CO2), 2191.807 t CO2", "Flaring (unburned CH4), 16.306 t CH4"]'::jsonb, 3, 'H3 (SECTION 25) points at SECTION 5, where the flare''s escaped carbon becomes ch4Tonnes 16.306 at 0.98; SECTION 7 carries it as Flaring (unburned CH4). The vented line''s 142.000 t comes from the survey, and the two CO2 lines are the carbon that burned.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Every other gap is closed and only the flare''s destruction efficiency is blank. What does the total leave out?', '["The flare''s CO2 line and its methane line", "The flare''s methane line alone, 485.922 tCO2e", "The vented and fugitive methane line", "Nothing, since the flare is read at 1"]'::jsonb, 0, 'SECTION 9 prints that inventory: 4 lines, Scope 1 27353.048, total 40268.048 tCO2e, reportable false. "The total leaves out the flare''s CO2 and methane lines, and the inventory is not reportable while the flare stands refused."'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Which flags does the complete Igbogene inventory return?', '["computed true, reportable false, blocked lines 0, unsourced lines 1", "computed true, reportable true, blocked lines 0, unsourced lines 1", "computed true, reportable true, blocked lines 0, unsourced lines 0", "computed false, reportable true, blocked lines 0, unsourced lines 0"]'::jsonb, 2, 'SECTION 7 prints: "gwpSetLabel: IPCC AR6 GWP100, fossil methane. computed: true. reportable: true. blocked lines: 0. unsourced lines: 0." SECTION 9 shows an unsourced factor keeps an inventory from being reportable.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Which Igbogene line rests on the Epie Creek leak detection survey (invented), version 2026 Q2?', '["Flaring (unburned CH4), 16.306 t CH4", "Vented and fugitive methane, 142.000 t CH4", "Purchased electricity, 31500.000 MWh", "Fired heaters (CO2), 23121.448 t CO2"]'::jsonb, 1, 'SECTION 7 prints the survey as the source of the Vented and fugitive methane line, activity 142.000 t CH4, factor 1 tCH4/t. The flare''s methane and the heaters are atom-balance lines, and the electricity line rests on the supplier statement (invented), 2025.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 6, 'What shares of the complete Igbogene total does the digest print for the flare''s two lines?', '["0.011315 for its CO2 and 0.051037 for its methane", "0.051037 for its CO2 and 0.181468 for its methane", "0.098534 for its CO2 and 0.011315 for its methane", "0.051037 for its CO2 and 0.011315 for its methane"]'::jsonb, 3, 'SECTION 7''s share table (computed here) prints Flaring (CO2) 0.051037 and Flaring (unburned CH4) 0.011315. 0.181468 is a share of the flare alone (SECTION 5), and 0.098534 belongs to the vented line.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 7, 'What factor does SECTION 7 give the atom-balance lines, as the Carbon Studio builds them?', '["A factor of 1 whose source is conservation of mass", "The heaters'' 1.09 kmol of carbon per kmol of fuel", "MW_CO2, 44.009, whose source is the IUPAC weights", "The set''s CH4 value, 29.8, applied as the factor"]'::jsonb, 0, 'SECTION 7: "The atom-balance lines carry a factor of 1 whose source is conservation of mass, as the Carbon Studio builds them." The factor column reads 1 on all three atom-balance lines; 29.8 sits in the GWP column of the methane lines, on IPCC AR6 GWP100, fossil methane.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 8, 'How many lines make up Scope 1 in the complete Igbogene inventory, and what do they total?', '["5 lines, 42945.777 tCO2e", "4 lines, 27353.048 tCO2e", "4 lines, 30030.777 tCO2e", "3 lines, 30030.777 tCO2e"]'::jsonb, 2, 'SECTION 7: "Scope 1 is the sum of its 4 lines" and prints Scope 1 (direct) at 30030.777 tCO2e. 42945.777 is the total of both scopes, and 27353.048 is Scope 1 with the flare''s efficiency still blank.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 9, 'What activity and unit does the Fired heaters (CO2) line carry into the inventory?', '["482000 kmol of fuel", "525380.000 kmol of carbon", "31500.000 MWh", "23121.448 t CO2"]'::jsonb, 3, 'SECTION 7 gives the heaters'' line an activity of 23121.448 in t CO2, the co2Tonnes SECTION 4 returns. 482000 kmol is the fuel typed in, 525380.000 kmol the carbon counted from it, and 31500.000 MWh the electricity line''s activity.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 10, 'At the heaters'' typed destruction efficiency of 1, what do ch4Tonnes and unburnedNote read?', '["ch4Tonnes 0.000 and unburnedNote none", "ch4Tonnes 8.429 and unburnedNote none", "ch4Tonnes 0.000 and the escaped carbon note", "ch4Tonnes 42.143 and the escaped carbon note"]'::jsonb, 0, 'SECTION 4 prints the heaters at 1: carbonKmolPerYear 525380.000, co2Tonnes 23121.448, ch4Tonnes 0.000, unburnedNote none. 8.429 and 42.143 are the methane at 0.999 and at 0.995.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 11, 'The complete inventory''s total intensity over inlet to export is 0.01176597. Which tonnes over which denominator does the digest give for it?', '["30030.777 tCO2e over 3650000", "42945.777 tCO2e over 3650000", "42945.777 tCO2e over 2410000", "12915.000 tCO2e over 3650000"]'::jsonb, 1, 'SECTION 10: "42945.777 tCO2e over 3650000 is 0.01176597 (computed here), the engine''s total intensity on the first boundary." 2410000 is the crude export only denominator. The Scope 1 and Scope 2 intensities on the first boundary are 0.00822761 and 0.00353836.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 12, 'On the course''s set, what scope and GWP does each methane line carry?', '["Scope 1 for the flare and Scope 2 for the vented line", "Scope 1, the flare at 29.8 and the vented line at 27", "Scope 1, both at 29.8 on the course''s set", "Scope 2, both at a GWP of 1 on the course''s set"]'::jsonb, 2, 'SECTION 7 prints Flaring (unburned CH4) and Vented and fugitive methane on scope 1, gas CH4, GWP 29.8, on IPCC AR6 GWP100, fossil methane. 27 is the AR6 non-fossil value, and Scope 2 holds only the purchased electricity line.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Which lines of the complete inventory carry the source Atom balance (conservation of mass)?', '["Fired heaters (CO2), Flaring (CO2) and Flaring (unburned CH4)", "Fired heaters (CO2) and Flaring (CO2), with no methane line", "All five lines, the electricity line through its 0.41 factor", "Fired heaters (CO2) alone, the one burner line of the five"]'::jsonb, 0, 'SECTION 7 prints three lines with the source "Atom balance (conservation of mass)" and version "not applicable": the fired heaters, the flare''s CO2 and the flare''s unburned CH4. The vented line rests on the survey and the electricity line on the supplier statement.'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 14, 'At which step of the Igbogene build does the line count go from 4 to 5?', '["The GWP set declared", "The electricity factor entered with its source", "The survey referenced", "The flare efficiency entered"]'::jsonb, 3, 'SECTION 9''s lines column reads 4, 4, 5, 5, 5, and the flare efficiency entered is the step where it moves. SECTION 5 turns a refused flare into 1 blocked line, and SECTION 7 carries the computed flare as two lines, Flaring (CO2) and Flaring (unburned CH4).'),
  ('carbon', 'beginner', 'module', 'm06-the-associate-reading', 15, 'The Igbogene first pass totals 23121.448 tCO2e. What do its computed and reportable flags read?', '["computed false and reportable false", "computed true and reportable false", "computed true and reportable true", "computed false and reportable true"]'::jsonb, 1, 'SECTION 9 prints the first pass with 4 lines, Scope 1 23121.448, Scope 2 0.000, computed true, reportable false, because the global warming potential set is not declared and 3 line(s) could not be computed.'),
  ('carbon', 'beginner', 'final', null, 1, 'The digest separates a blank box from an argument left out of the call. How does each reach the engine?', '["Both arrive as 0, and the interval check on the destruction efficiency refuses each of them.", "A blank takes the stated default; an argument left out of the call is refused as required.", "A blank arrives as an empty string or null; a left-out argument takes its stated default.", "Both take the stated default wherever one exists, and are refused only where none exists."]'::jsonb, 2, 'SECTION 2 opens with this distinction. It prints a blank or a null flare efficiency refused as required, and the same argument left out of the call answering destructionEfficiencyFraction 1, its stated default of complete combustion.'),
  ('carbon', 'beginner', 'final', null, 2, 'Which module does the Carbon Footprint & Abatement Studio call?', '["carbonAbatement", "energyEfficiency", "energyEfficiency, through priceSaving", "energyEfficiency for its fuel table"]'::jsonb, 0, 'SECTION 1 pairs each studio with one module: the Carbon Footprint & Abatement Studio with carbonAbatement, the Efficiency Studio with energyEfficiency.'),
  ('carbon', 'beginner', 'final', null, 3, 'Which label does the Scope 2 total carry in buildInventory''s output?', '["Scope 2 (direct)", "Scope 2 (energy and travel)", "Scope 2 (indirect, all other)", "Scope 2 (purchased energy)"]'::jsonb, 3, 'The SECTION 7 totals table reads Scope 1 (direct), Scope 2 (purchased energy) and Total, Scope 1 and Scope 2.'),
  ('carbon', 'beginner', 'final', null, 4, 'Refusing an intensity with no boundary, the engine names two figures that differ for one plant. Which two?', '["Tonnes per barrel produced and tonnes per barrel exported", "Tonnes per tonne charged and tonnes per tonne of saleable product", "The Scope 1 intensity and the Scope 2 intensity of one plant", "tCO2e on the AR6 sets and tCO2e on the AR5 sets of one year"]'::jsonb, 1, 'The carbonIntensity refusal in SECTION 2 names tonnes per tonne charged and tonnes per tonne of saleable product. The Igbogene boundaries are per barrel, and they are inputs to the call.'),
  ('carbon', 'beginner', 'final', null, 5, 'Which factor unit does the Purchased electricity line carry?', '["tCO2/tCO2", "tCO2/MWh", "tCH4/t", "tCH4/tCH4"]'::jsonb, 1, 'SECTION 7 prints the factor unit tCO2/MWh on Purchased electricity, beside Igbogene''s invented factor of 0.41. tCO2/tCO2 and tCH4/tCH4 belong to the atom-balance lines and tCH4/t to the vented line.'),
  ('carbon', 'beginner', 'final', null, 6, 'Typing 98 as the flare''s efficiency, meant as a percentage, produces what?', '["It computes at 0.98, reading the 98 as a percentage", "It computes at the stated default of complete combustion", "REFUSED: A fuel quantity and a carbon content cannot be negative.", "REFUSED: The destruction efficiency must lie in (0, 1]."]'::jsonb, 3, 'SECTION 2 prints this refusal for 98 typed as a percentage, the same sentence it prints for 0. The flare''s stated efficiency is typed as the fraction 0.98.'),
  ('carbon', 'beginner', 'final', null, 7, 'Which pair does the 1000 kmol table print at 0.99?', '["43.569 t of CO2 and 0.160 t of methane", "44.009 t of CO2 and 0.160 t of methane", "43.129 t of CO2 and 0.321 t of methane", "43.569 t of CO2 and 0.802 t of methane"]'::jsonb, 0, 'Row 0.99 of the SECTION 3 table: co2Tonnes 43.569, ch4Tonnes 0.160. 44.009 belongs to complete combustion, and 0.321 and 0.802 are the methane at 0.98 and 0.95.'),
  ('carbon', 'beginner', 'final', null, 8, 'Typed at 1.15 kmol of carbon per kmol, with the fuel unchanged, what do the Igbogene heaters emit?', '["23121.448 t", "21212.338 t", "24394.189 t", "25799.177 t"]'::jsonb, 2, 'The carbon per kmol table in SECTION 4 gives 24394.189 at 1.15. 25799.177 is not a heater figure; it is an inventory total with two blocked lines.'),
  ('carbon', 'beginner', 'final', null, 9, 'Which pair is the Igbogene heaters'' 0.999 row?', '["co2Tonnes 23121.448, ch4Tonnes 8.429", "co2Tonnes 23005.841, ch4Tonnes 42.143", "co2Tonnes 23098.327, ch4Tonnes 42.143", "co2Tonnes 23098.327, ch4Tonnes 8.429"]'::jsonb, 3, 'SECTION 4''s lower-efficiency table: 0.999 gives 23098.327 and 8.429; 0.995 gives 23005.841 and 42.143.'),
  ('carbon', 'beginner', 'final', null, 10, 'Which carbonAbatement constant reads 12.011?', '["MW_CH4, the molar mass of methane", "MW_C, the molar mass of carbon", "MW_CO2, the molar mass of CO2", "SCOPE, beside ONE 1 and TWO 2"]'::jsonb, 1, 'The constants block of SECTION 1 lists MW_C as 12.011, beside MW_CO2 44.009 and MW_CH4 16.043.'),
  ('carbon', 'beginner', 'final', null, 11, 'Which FUEL_REFERENCE row is marked inert and still carries one carbon atom?', '["CO2, Carbon dioxide (inert)", "N2, Nitrogen (inert)", "CH4, Methane", "C2H6, Ethane"]'::jsonb, 0, 'In FUEL_REFERENCE the CO2 row has C 1, O 2 and inert yes; N2 is inert with no carbon.'),
  ('carbon', 'beginner', 'final', null, 12, 'Which figure is the Igbogene flare''s CO2 when it burns at 0.9?', '["2124.711", "2236.537", "2012.884", "2191.807"]'::jsonb, 2, 'The flare row at 0.9 in SECTION 5 reads co2Tonnes 2012.884, beside 81.531 t of methane.'),
  ('carbon', 'beginner', 'final', null, 13, 'Which row of the flare table totals 2457.133 tCO2e?', '["0.98, with 16.306 t of methane", "0.95, with 40.765 t of methane", "0.9, with 81.531 t of methane", "0.99, with 8.153 t of methane"]'::jsonb, 3, 'In SECTION 5 the 0.99 row prints a flare total of 2457.133 and ch4Tonnes 8.153. Rows 0.98, 0.95 and 0.9 total 2677.729, 3339.515 and 4442.493.'),
  ('carbon', 'beginner', 'final', null, 14, 'Read the 0.95 row of the Igbogene flare table. What is ch4Tonnes?', '["81.531 t of methane", "40.765 t of methane", "16.306 t of methane", "1214.805 t of methane"]'::jsonb, 1, 'SECTION 5, row 0.95: ch4Tonnes 40.765. Its methane line, 1214.805, is in tCO2e and is a different quantity.'),
  ('carbon', 'beginner', 'final', null, 15, 'The escaped-carbon note ends with an instruction for a user holding a measurement. What is it?', '["File the measurement in the compliance register", "Switch the set to the non-fossil methane value", "Override it", "Leave the flare efficiency blank until refused"]'::jsonb, 2, 'The last sentence of the escaped-carbon note in SECTION 5 is "Override it if you have measured otherwise."'),
  ('carbon', 'beginner', 'final', null, 16, 'A source is kept outside the boundary on purpose, excluded true. How many lines does atomBalanceLines hand the inventory?', '["0 lines", "1 blocked line", "2 lines at 0.000 t", "1 unsourced line"]'::jsonb, 0, 'SECTION 9 prints 0 lines for excluded true. A refused flare, by contrast, arrives as one blocked line labelled Flaring.'),
  ('carbon', 'beginner', 'final', null, 17, 'On the AR5 non-fossil set, the flare''s escaped carbon becomes a line of how many tCO2e?', '["440.265 tCO2e", "489.183 tCO2e", "485.922 tCO2e", "456.571 tCO2e"]'::jsonb, 3, '456.571 is the AR5 non-fossil entry in the SECTION 8 methane table; 440.265 and 489.183 are AR6 non-fossil and AR5 fossil.'),
  ('carbon', 'beginner', 'final', null, 18, 'How far above or below the course set does the digest place the Igbogene total on AR5 fossil methane?', '["-443.257 tCO2e", "31.661 tCO2e", "-284.951 tCO2e", "0.000 tCO2e"]'::jsonb, 1, 'SECTION 8 reads 42977.438 for AR5 fossil, and its computed-here column puts that 31.661 above the course set''s 42945.777.'),
  ('carbon', 'beginner', 'final', null, 19, 'The held item H1 records where AR5 and AR6 each stand. What does it say?', '["AR6 is what UNFCCC reporting has required; AR5 is what the GHG Protocol now recommends.", "AR5 and AR6 are both what UNFCCC reporting requires, so the course recommends AR6.", "AR5 is what UNFCCC reporting has required; AR6 is what the GHG Protocol now recommends.", "AR6 is what Nigerian regulation requires; AR5 is kept only for comparing old years."]'::jsonb, 2, 'Held item H1 prints both positions and then holds the choice: a regulatory reading and the owner''s decision, graded nowhere.'),
  ('carbon', 'beginner', 'final', null, 20, 'What N2O value sits in the course''s own set?', '["273", "265", "29.8", "27"]'::jsonb, 0, 'The course''s set is CH4 29.8 and N2O 273 (SECTION 6). The AR5 sets carry 265.'),
  ('carbon', 'beginner', 'final', null, 21, 'makeGwpSet is given a label and no values. What does the set read?', '["declared true", "declared true, with 0 gases", "refused, with no set at all", "declared false"]'::jsonb, 3, 'The SECTION 6 declared table reads false for a label with no values and false for values with no label.'),
  ('carbon', 'beginner', 'final', null, 22, 'The flare efficiency is entered with the GWP set already declared. What reasons for not being reportable does buildInventory then give?', '["the global warming potential set is not declared; 3 line(s) could not be computed", "1 factor(s) have no source or version; 1 line(s) could not be computed", "1 factor(s) have no source or version; 2 line(s) could not be computed", "none, and reportable reads true"]'::jsonb, 1, 'That is the "flare efficiency entered" row of SECTION 9: 5 lines, Scope 1 30030.777, and the electricity factor still blank.'),
  ('carbon', 'beginner', 'final', null, 23, 'At which step does the Igbogene Scope 2 total first read 12915.000 tCO2e?', '["The electricity factor entered with its source", "The GWP set declared", "The flare efficiency entered", "The first pass"]'::jsonb, 0, 'SECTION 9 gives Scope 2 as 0.000 on the first three rows; the electricity factor entered with its source brings in the 12915.000.'),
  ('carbon', 'beginner', 'final', null, 24, 'Across the five Igbogene steps, what does the computed flag read?', '["false until the survey is referenced", "false in the first pass only", "true at every step", "true once the set is declared"]'::jsonb, 2, 'Every row of the SECTION 9 step table reads computed true. The reportable flag is the one that turns, on the last row.'),
  ('carbon', 'beginner', 'final', null, 25, 'The vented activity is typed as -142 t and the electricity factor as -0.41. What does that inventory return?', '["a total of 42945.777 tCO2e with reportable true", "a total of 25799.177 tCO2e with reportable true", "a refusal of the whole inventory, with no total", "a total of 25799.177 tCO2e with reportable false"]'::jsonb, 3, 'SECTION 9 blocks both negative lines and prints the inventory at 25799.177, reportable false, with 2 line(s) that could not be computed.'),
  ('carbon', 'beginner', 'final', null, 26, 'Which Scope 2 intensity does the inlet to export boundary carry?', '["0.00822761", "0.00353836", "0.00535892", "0.01176597"]'::jsonb, 1, 'SECTION 10''s inlet to export row: Scope 1 0.00822761, Scope 2 0.00353836, total 0.01176597. 0.00535892 is the crude export only Scope 2.'),
  ('carbon', 'beginner', 'final', null, 27, 'Which denominator and unit sit under the boundary "Igbogene crude export only"?', '["2410000 barrels of oil exported", "3650000 barrels of oil exported", "2410000 barrels of oil equivalent produced", "3650000 barrels of oil equivalent produced"]'::jsonb, 0, 'The two boundary rows of SECTION 10 carry 3650000 in barrels of oil equivalent produced and 2410000 in barrels of oil exported, both invented.'),
  ('carbon', 'beginner', 'final', null, 28, 'The inventory disclaimer warns against keeping a second copy of obligations in the inventory. What would the copy create?', '["A blocked line for each obligation", "A total that counts each tonne twice", "An unsourced factor in the register", "Two records that could disagree"]'::jsonb, 3, 'The disclaimer in SECTION 7 ends: keeping a second copy of them here would create two records that could disagree.'),
  ('carbon', 'beginner', 'final', null, 29, 'Which share of the complete total belongs to the vented and fugitive methane?', '["0.300728", "0.538387", "0.098534", "0.011315"]'::jsonb, 2, 'From the SECTION 7 share table (computed here): 0.098534 for vented methane, 0.300728 for electricity, 0.538387 for the heaters.'),
  ('carbon', 'beginner', 'final', null, 30, 'Which activity and factor does the Vented and fugitive methane line carry?', '["16.306 t CH4 at a factor of 1 tCH4/tCH4", "142.000 t CH4 at a factor of 1 tCH4/t", "142.000 t CH4 at a factor of 29.8 tCH4/t", "4231.600 t CH4 at a factor of 1 tCH4/t"]'::jsonb, 1, 'SECTION 7 gives the vented line an activity of 142.000 t CH4 and a factor of 1 tCH4/t. 29.8 is the CH4 value of IPCC AR6 GWP100, fossil methane, the line''s GWP; 4231.600 is its tCO2e.'),
  ('carbon', 'beginner', 'final', null, 31, 'A blocked electricity line leaves the inlet to export total intensity equal to which figure of the complete inventory?', '["Its Scope 1 intensity, 0.00822761", "Its Scope 2 intensity, 0.00353836", "Its total intensity, 0.01176597", "Its crude export Scope 1, 0.01246090"]'::jsonb, 0, 'SECTION 10 compares the two and prints them as the same figure: with the Scope 2 line blocked, the total is Scope 1 alone.'),
  ('carbon', 'beginner', 'final', null, 32, 'Held item H2 names the engine''s typical heating values for methane. Which pair does it give?', '["890.8 LHV and 802.6 HHV MJ per kmol", "1428.6 LHV and 1560.7 HHV MJ per kmol", "241.8 LHV and 285.8 HHV MJ per kmol", "802.6 LHV and 890.8 HHV MJ per kmol"]'::jsonb, 3, 'SECTION 25, H2: the engine''s typical methane heating values are 802.6 LHV and 890.8 HHV MJ per kmol; the pair is labelled typical and the fuel analysis governs. FUEL_REFERENCE prints 1428.6 and 1560.7 for ethane and 241.8 and 285.8 for hydrogen.'),
  ('carbon', 'beginner', 'final', null, 33, 'How many lines does the Igbogene first pass build, and how many of them are blocked?', '["5 lines, 3 of them blocked", "4 lines, 1 of them blocked", "4 lines, 3 of them blocked", "5 lines, none of them blocked"]'::jsonb, 2, 'SECTION 9 counts the first pass at 4 lines, with 3 blocked and 0 unsourced.'),
  ('carbon', 'beginner', 'final', null, 34, '21212.338 t of CO2 is the heaters'' figure at which carbon per kilomole of fuel?', '["1.05", "1.00", "1.09", "1.15"]'::jsonb, 1, 'In SECTION 4, 1.00 is the row at 21212.338; 1.09 is the Igbogene input.'),
  ('carbon', 'beginner', 'final', null, 35, 'Which co2Tonnes figure belongs to the flare''s 0.99 row?', '["2214.172", "2191.807", "2236.537", "2457.133"]'::jsonb, 0, 'Flare row 0.99 in SECTION 5 reads co2Tonnes 2214.172; 2457.133 on that row is the total in tCO2e.'),
  ('carbon', 'beginner', 'final', null, 36, 'How does the engine''s note describe counting escaped carbon as methane?', '["As a measured result for each flare", "As the AR6 non-fossil convention", "As a default set by the owner", "As the usual and conservative assumption"]'::jsonb, 3, 'The SECTION 5 note calls it "the usual and conservative assumption" and says to override it if you have measured otherwise. H3 holds it as the engine''s stated assumption.'),
  ('carbon', 'beginner', 'final', null, 37, 'Typed at 0.95 in place of the stated 0.98, where does the flare''s unburned methane line go?', '["From 485.922 to 2429.610 tCO2e", "From 16.306 to 40.765 tCO2e", "From 485.922 to 1214.805 tCO2e", "Nowhere; only the CO2 line moves"]'::jsonb, 2, 'From the 0.98 row to the 0.95 row of SECTION 5 the methane line goes from 485.922 to 1214.805 tCO2e. 16.306 and 40.765 are tonnes of methane.'),
  ('carbon', 'beginner', 'final', null, 38, 'Switched from the AR6 fossil set to the AR6 non-fossil set, where does the flare''s unburned methane line go?', '["To 489.183 tCO2e", "To 440.265 tCO2e", "To 456.571 tCO2e", "Nowhere; it stays 485.922"]'::jsonb, 1, 'SECTION 8 lists the flare''s methane line as 485.922 on AR6 fossil and 440.265 on AR6 non-fossil; the AR5 figures are 489.183 and 456.571.'),
  ('carbon', 'beginner', 'final', null, 39, 'Which Igbogene figure holds still across all four GWP sets?', '["Scope 1, 30030.777 tCO2e", "The total, 42945.777 tCO2e", "The vented line, 4231.600 tCO2e", "Scope 2, 12915.000 tCO2e"]'::jsonb, 3, 'Scope 2 is a CO2 line with a GWP of 1 whatever the set, so SECTION 8 prints 12915.000 four times.'),
  ('carbon', 'beginner', 'final', null, 40, 'Which flare tCO2e sits on the stated 0.98 row?', '["2677.729 tCO2e", "2236.537 tCO2e", "2191.807 tCO2e", "3339.515 tCO2e"]'::jsonb, 0, 'The SECTION 5 row at 0.98 prints a flare total of 2677.729, of which 2191.807 is CO2.'),
  ('carbon', 'beginner', 'final', null, 41, 'Which sentence explains a scope 3 line''s block?', '["A registered emission factor is required.", "no global warming potential for CH4 in the declared set", "scope 3 is not Scope 1 or Scope 2, which is all this inventory totals", "a negative activity: an emission line cannot remove tonnes"]'::jsonb, 2, 'SECTION 9 prints this reason for the scope 3 Business travel line. The factor refusal belongs to Diesel generators, the missing GWP blocks the vented methane in the first pass, and the negative activity blocks the vented methane typed as -142 t.'),
  ('carbon', 'beginner', 'final', null, 42, 'Which boundary''s intensity is stated in tCO2e per barrel of oil equivalent produced?', '["Igbogene crude export only", "Igbogene flow station and gas plant, inlet to export", "Igbogene fired heaters and flare only", "Igbogene Scope 1 lines only"]'::jsonb, 1, 'SECTION 10 gives the inlet to export boundary in barrels of oil equivalent produced and crude export only in barrels of oil exported.');
